// w6b8-aps-load: the upgrade marker (ensure + assert match this)
const ENGINE = String(window.__W6_ENGINE_BASE__ || 'http://127.0.0.1:13110');
const TOKEN = localStorage.getItem('NOCOBASE_TOKEN') || '';
const AMP = '\u0026';
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': AMP + 'amp;', '<': AMP + 'lt;', '>': AMP + 'gt;', '"': AMP + 'quot;', "'": AMP + '#39;' }[c]));
const state = { data: null, note: '' };
const api = async (path) => {
  const resp = await fetch(ENGINE + path, { headers: { authorization: 'Bearer ' + TOKEN } });
  return { status: resp.status, ok: resp.ok, json: await resp.json().catch(() => ({})) };
};
const heatBg = (util) => {
  if (util <= 0) return 'transparent';
  if (util >= 100) return 'rgba(255,77,79,' + Math.min(0.85, 0.35 + (util - 100) / 200).toFixed(2) + ')';
  if (util >= 80) return 'rgba(250,173,20,' + (0.25 + 0.3 * (util - 80) / 20).toFixed(2) + ')';
  return 'rgba(82,196,26,' + (0.12 + 0.3 * util / 80).toFixed(2) + ')';
};
const load = async () => {
  const out = await api('/aps/load?days=14');
  if (out.json && out.json.ok) { state.data = out.json; state.note = ''; }
  else state.note = '✗ 负荷数据加载失败（' + esc((out.json && (out.json.message || out.json.error)) || ('HTTP ' + String(out.status))) + '）';
  paint();
};
function paint() {
  const root = document.querySelector('[data-w6b8="aps-load"]');
  if (!root) return;
  const d = state.data;
  if (!d) { root.innerHTML = '<div style="color:#888;padding:8px">' + esc(state.note || '加载中…') + '</div>'; return; }
  const bn = d.bottlenecks || [];
  const worst = bn[0] || null;
  const kpi = '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">'
    + '<div style="border:1px solid #ffa39e;background:#fff1f0;border-radius:8px;padding:8px 14px"><div style="font-size:12px;color:#8c8c8c">超载桶（负荷率>100% 且含开放工序）</div><div style="font-size:22px;font-weight:800;color:#cf1322">' + String(bn.length) + '</div></div>'
    + (worst ? '<div style="border:1px solid #d9d9d9;border-radius:8px;padding:8px 14px"><div style="font-size:12px;color:#8c8c8c">最重瓶颈</div><div style="font-size:16px;font-weight:700">' + esc(worst.wc_code) + ' · ' + esc(worst.date) + ' · <span style="color:#cf1322">' + String(worst.util_pct) + '%</span></div></div>' : '')
    + '<div style="border:1px solid #d9d9d9;border-radius:8px;padding:8px 14px"><div style="font-size:12px;color:#8c8c8c">可重排 MO（含 planned 工序）</div><div style="font-size:22px;font-weight:800">' + String((d.open_mos || []).length) + '</div></div>'
    + '<div style="border:1px solid #d9d9d9;border-radius:8px;padding:8px 14px;flex:1;min-width:220px"><div style="font-size:12px;color:#8c8c8c">口径</div><div style="font-size:12px;color:#555">负荷率 = 已分配工时 ÷ 可用工时（mfg_work_centers 班次跨度×并行数，与 FCS 排产同式）；瓶颈 = 负荷率>100% 且仍有开放工序的桶</div></div></div>';
  const bnTable = bn.length === 0
    ? '<div style="color:#389e0d;padding:8px 0">当前无超载工作中心桶 ✓</div>'
    : '<table style="border-collapse:collapse;width:100%;font-size:12px"><thead><tr style="background:#fafafa;color:#666">'
