      + '<div style="font-size:11px;color:#888;margin-bottom:6px">合计 ¥' + String(amount.toLocaleString('zh-CN')) + '</div>'
      + (cardHtml || '<div style="color:#bbb;font-size:12px">（空）</div>') + '</div>';
  }).join('');
  const supplierOptions = '<option value="0">全部供应商</option>' + suppliers.map(s => '<option value="' + String(s.id) + '" ' + (Number(s.id) === state.supplier ? 'selected' : '') + '>' + esc(s.name) + '</option>').join('');
  root.innerHTML = [
    '<div style="display:flex;gap:10px;align-items:center;margin-bottom:8px;flex-wrap:wrap">',
    '<b>采购订单泳道</b><span style="color:#888;font-size:12px">（按审批状态分组 · 只读——状态由审批引擎驱动）</span>',
    '<span style="flex:1"></span>',
