const mk = async (name, size) => {
  const r = ctx.makeResource('MultiRecordResource');
  r.setResourceName(name);
  r.setPageSize(size);
  await r.refresh();
  return r.getData() || [];
};
const lots = await mk('wms_lots', 500);
const products = await mk('hub_inv_products', 500);
const moves = await mk('wms_movements', 1000);
const alerts = (await mk('wfl_alerts', 500)).filter(a => a.rule_type === 'expiry');
const expiryRule = (await mk('alert_rules', 50)).find(r => r.rule_type === 'expiry');
const warnDays = Number(expiryRule && expiryRule.params && expiryRule.params.warn_days) > 0 ? Number(expiryRule.params.warn_days) : 30;
const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/'/g,'&#39;').replace(/"/g,'&quot;')
const prodOf = {};
for (const p of products) prodOf[p.id] = p;
const onHand = {};
for (const m of moves) onHand[m.lot_id] = (onHand[m.lot_id] || 0) + Number(m.qty || 0);
const today = new Date();
const dayDiff = (d) => d == null ? null : Math.round((new Date(String(d) + 'T00:00:00Z').getTime() - today.getTime()) / 86400000);
const regTier = (pdate, edate) => {
  if (!pdate || !edate) return 45;
  const shelf = Math.round((new Date(edate) - new Date(pdate)) / 86400000);
  if (shelf >= 365) return 45;
  if (shelf >= 180) return 20;
  if (shelf >= 90) return 15;
  if (shelf >= 30) return 10;
  return 3;
};
const alertOf = {};
for (const a of alerts) { if (a.status !== 'resolved') alertOf[a.entity_id] = a; }
const rows = lots.map(l => {
  const p = prodOf[l.product_id] || {};
  const left = dayDiff(l.expiry_date);
  const tier = regTier(l.production_date, l.expiry_date);
  const bucket = left == null ? 'nodate' : left < 0 ? 'expired' : left <= Math.min(warnDays, tier) ? 'critical' : left <= 90 ? 'warn' : 'ok';
  return { lot: l, prod: p, left, tier, bucket,
    qty: onHand[l.id] || 0,
    alert: alertOf[l.id] || null,
    cat: p.category || '未分类', zone: p.temp_zone || '—' };
});
const BUCKETS = [['expired','已过期'],['critical','临期(监管线)'],['warn','30-90天'],['ok','>90天'],['nodate','缺日期']];
const BCOLOR = { expired:'#ff4d4f', critical:'#fa541c', warn:'#faad14', ok:'#52c41a', nodate:'#bfbfbf' };
const kpi = { near: 0, expired: 0, week: 0, month: 0, openAlerts: 0 };
for (const r of rows) {
  if (r.bucket === 'expired') { kpi.expired++; kpi.near++; }
  else if (r.bucket === 'critical') { kpi.near++; if (r.left != null && r.left <= 7) kpi.week++; if (r.left != null && r.left <= 30) kpi.month++; }
  if (r.alert) kpi.openAlerts++;
}
const card = (n, label, color) => `<div style="flex:1;min-width:120px;background:#fff;border-radius:10px;padding:10px 14px;box-shadow:0 1px 4px rgba(0,0,0,.08)"><div style="font-size:26px;font-weight:700;color:${color}">${n}</div><div style="font-size:12px;color:#666">${label}</div></div>`;
const kpiBand = `<div style="display:flex;gap:10px;margin:8px 0;flex-wrap:wrap">`
  + card(kpi.near, '临期+过期批次', '#fa541c')
  + card(kpi.expired, '已过期待处置', '#ff4d4f')
  + card(kpi.week, '≤7天到期', '#fa8c16')
  + card(kpi.month, '≤30天到期', '#faad14')
  + card(kpi.openAlerts, '效期预警未关闭(B2)', '#1677ff')
  + `</div>`;
const cats = [...new Set(rows.map(r => r.cat))].sort();
let matrix = '';
window.__expiryDrill = null;
for (const cat of cats) {
  let cells = '';
  for (const [bk, bl] of BUCKETS) {
    const hit = rows.filter(r => r.cat === cat && r.bucket === bk);
    const strong = bk === 'expired' || bk === 'critical';
    cells += `<td style="padding:0"><div data-expiry-cell="${cat}|${bk}" style="margin:2px;min-width:86px;height:34px;border-radius:6px;display:flex;align-items:center;justify-content:center;cursor:${hit.length ? 'pointer' : 'default'};background:${hit.length ? BCOLOR[bk] : '#f5f5f5'};color:${hit.length ? '#fff' : '#bbb'};font-weight:${strong && hit.length ? 700 : 400}" title="${esc(hit.map(r => r.lot.lot_no + '(' + (r.left == null ? '?' : r.left) + '天)').join('、'))}">${hit.length}</div></td>`;
  }
  matrix += `<tr><th style="text-align:left;padding:4px 10px 4px 2px;font-weight:600">${cat}<div style="font-size:11px;color:#999;font-weight:400">温区 ${[...new Set(rows.filter(r => r.cat === cat).map(r => r.zone))].join('/')}</div></th>${cells}</tr>`;
}
const legend = BUCKETS.map(([bk, bl]) => `<span style="color:${BCOLOR[bk]}">■ ${bl}</span>`).join('　') + `　<span style="color:#888">红档=LEAST(${warnDays},监管分档)（≥1年→45 / 半年→20 / 90天→15 / 30天→10 / 更短→3）——红线天数读自 alert_rules.warn_days，与 B2 规则引擎同口径</span>`;
const table = rows.map(r => `<tr data-expiry-row="1"><td style="padding:2px 8px">${esc(r.lot.lot_no)}</td><td style="padding:2px 8px">${esc(r.prod.name || '—')}</td><td style="padding:2px 8px">${String(r.lot.production_date || '—')}</td><td style="padding:2px 8px">${String(r.lot.expiry_date || '—')}</td><td style="padding:2px 8px;color:${BCOLOR[r.bucket]}">${r.left == null ? '缺' : r.left + '天'}</td><td style="padding:2px 8px">${r.qty}</td><td style="padding:2px 8px">${esc(r.lot.status || '—')}</td><td style="padding:2px 8px">${r.alert ? (r.alert.status === 'open' ? '🔴未处理' : '🟠已认领') : '—'}</td></tr>`).join('');
const detailTable = `<div id="expiry-drill" style="margin-top:10px;display:none"><div style="font-weight:600;margin:6px 0" id="expiry-drill-title"></div><table style="border-collapse:collapse;font-size:12px;width:100%"><thead><tr style="color:#888"><th style="text-align:left">批次</th><th style="text-align:left">品名</th><th style="text-align:left">生产日期</th><th style="text-align:left">到期日</th><th style="text-align:left">剩余</th><th style="text-align:left">在库</th><th style="text-align:left">状态</th><th style="text-align:left">预警</th></tr></thead><tbody id="expiry-drill-body">${table}</tbody></table></div>`;
const html = `<div data-w6b3="expiry-board" style="padding:8px;font-family:system-ui">`
  + kpiBand
  + `<div style="font-size:12px;margin:6px 0">${legend}</div>`
  + `<table style="border-collapse:separate"><thead><tr><th></th>${BUCKETS.map(([, bl]) => `<th style="padding:2px 6px;font-size:12px;color:#555">${bl}</th>`).join('')}</tr></thead><tbody>${matrix}</tbody></table>`
  + `<div style="font-size:12px;color:#888;margin-top:4px">点击色格下钻该品类该档批次清单；「在库」= wms_movements 台账聚合（Σ流水）</div>`
  + detailTable
  + `</div>`;
ctx.render(html);
setTimeout(() => {
  const drill = document.querySelector('#expiry-drill');
  const title = document.querySelector('#expiry-drill-title');
  const body = document.querySelector('#expiry-drill-body');
  if (!drill) return;
  document.querySelectorAll('[data-expiry-cell]').forEach(cell => {
    cell.addEventListener('click', () => {
      const [cat, bk] = cell.getAttribute('data-expiry-cell').split('|');
      drill.style.display = 'block';
      title.textContent = `下钻：${cat} · ${BUCKETS.find(b => b[0] === bk)[1]}`;
      body.innerHTML = table;
      for (const tr of body.querySelectorAll('tr[data-expiry-row]')) tr.style.display = 'none';
      const catRows = rows.filter(r => r.cat === cat && r.bucket === bk);
      const lotNos = new Set(catRows.map(r => r.lot.lot_no));
      for (const tr of body.querySelectorAll('tr[data-expiry-row]')) {
        const first = tr.querySelector('td');
        if (first && lotNos.has(first.textContent)) tr.style.display = '';
      }
    });
  });
}, 0);

