// w6b7-matrix: the upgrade marker (ensureJsBlockOnPage + assert match this)
const ENGINE = String(window.__W6_ENGINE_BASE__ || 'http://127.0.0.1:13110');
const TOKEN = localStorage.getItem('NOCOBASE_TOKEN') || '';
const AMP = '\u0026';
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': AMP + 'amp;', '<': AMP + 'lt;', '>': AMP + 'gt;', '"': AMP + 'quot;', "'": AMP + '#39;' }[c]));
const state = { rfqs: [], rfq: ((window.location.search || '').match(/[?&]rfq=([^&]+)/) || [])[1] || '', matrix: null, awards: [], note: '', modal: 0 };
const api = async (path, post) => {
  const resp = await fetch(ENGINE + path, post === undefined
    ? { headers: { authorization: 'Bearer ' + TOKEN } }
    : { method: 'POST', headers: { authorization: 'Bearer ' + TOKEN, 'content-type': 'application/json' }, body: JSON.stringify(post) });
  return { status: resp.status, ok: resp.ok, json: await resp.json().catch(() => ({})) };
};
const loadRfqs = async () => {
  const out = await api('/sourcing/rfqs');
  state.rfqs = out.json.rfqs || [];
  if (!state.rfq) { const open = state.rfqs.find(r => r.doc_status !== 'awarded'); state.rfq = (open || state.rfqs[0] || {}).code || ''; }
};
const loadMatrix = async () => {
  state.matrix = null;
  if (!state.rfq) return;
  try {
    const out = await api('/sourcing/matrix?rfq=' + encodeURIComponent(state.rfq));
    if (out.json && out.json.ok) state.matrix = out.json;
    else state.note = '✗ RFQ 不存在或已关闭' + ((out.json && out.json.message) ? '（' + out.json.message + '）' : '（HTTP ' + String(out.status) + '）');
  } catch (e) {
    state.matrix = null;
    state.note = '✗ 比价矩阵加载失败（网络错误：' + String(e && e.message ? e.message : e) + '）';
  }
};
const loadAwards = async () => { state.awards = (await api('/sourcing/awards')).json.awards || []; };
const heat = (min, max, v) => {
  if (!(max > min)) return 'transparent';
  const r = Math.max(0, Math.min(1, (v - min) / (max - min)));
  return r <= 0.5 ? 'rgba(82,196,26,' + (0.10 + 0.22 * (0.5 - r) * 2).toFixed(2) + ')' : 'rgba(255,77,79,' + (0.10 + 0.22 * (r - 0.5) * 2).toFixed(2) + ')';
};
const badge = (kind, text) => kind === 'prevent'
  ? '<span style="background:#fff1f0;border:1px solid #ffa39e;color:#cf1322;border-radius:4px;padding:0 5px;font-size:11px">prevent ' + esc(text) + '</span>'
  : kind === 'warn' ? '<span style="background:#fffbe6;border:1px solid #ffe58f;color:#d48806;border-radius:4px;padding:0 5px;font-size:11px">warn ' + esc(text) + '</span>'
    : '<span style="background:#f6ffed;border:1px solid #b7eb8f;color:#389e0d;border-radius:4px;padding:0 5px;font-size:11px">准入 OK</span>';
const statusColor = (s) => ({ approved: '#389e0d', sent: '#1677ff', awarded: '#722ed1' }[s] || '#8c8c8c');
const fmt1 = (x) => (x == null ? '—' : String(x));
ctx.render('<div data-w6b7="matrix" style="padding:8px;font-family:system-ui"></div>');
const render = () => {
  const root = document.querySelector('[data-w6b7="matrix"]');
  if (!root) return;
  const m = state.matrix || {};
  const w = m.weights || { price: 50, lead: 30, quality: 20 };
  const rfqOptions = state.rfqs.map(r => '<option value="' + esc(r.code) + '" ' + (r.code === state.rfq ? 'selected' : '') + '>' + esc(r.code) + ' · ' + esc(r.doc_status) + ' · ' + String(r.submitted || 0) + '家报价' + (r.won > 0 ? ' · 已中标' : '') + '</option>').join('');
  let groupsHtml = state.rfqs.length === 0
    ? '<div style="color:#888;padding:8px 0">暂无可比价的询价单——仅 approved/sent/awarded 且有已提交报价的询价单会出现在此</div>'
    : '<div style="color:#888;padding:8px 0">选择一张询价单查看比价矩阵</div>';
  if (m.ok && m.groups) {
    groupsHtml = m.groups.map(g => {
      const ps = g.rows.map(r => r.unit_price); const ls = g.rows.map(r => r.lead_time_days).filter(v => v != null);
      const rows = g.rows.map(r => {
        const cell = 'padding:5px 8px;border-bottom:1px solid #f0f0f0;font-size:12px;vertical-align:top';
        const bar = '<div style="background:#f5f5f5;border-radius:4px;height:14px;width:110px;position:relative"><div style="background:#389e0d;border-radius:4px;height:14px;width:' + Math.max(3, Math.round(r.total_score)) + '%"></div><span style="position:absolute;left:6px;top:0;font-size:11px;line-height:14px;color:#fff;font-weight:700">' + fmt1(r.total_score) + '</span></div>';
        const choose = m.awarded
          ? '<span style="color:#999;font-size:12px">已定标</span>'
          : r.admission === 'prevent'
            ? '<button disabled title="' + esc(r.admission_note) + '" style="padding:2px 10px;border:1px solid #ffa39e;color:#cf1322;background:#fff1f0;border-radius:6px;font-size:12px;cursor:not-allowed">禁止定标</button>'
            : '<button data-act="choose" data-q="' + String(r.quote_id) + '" style="padding:2px 10px;border:1px solid #1677ff;color:#1677ff;background:#fff;border-radius:6px;font-size:12px;cursor:pointer">Choose 定标</button>';
        return '<tr>'
          + '<td style="' + cell + ';font-weight:700">#' + String(r.rank) + '</td>'
          + '<td style="' + cell + '"><b>' + esc(r.supplier_name) + '</b><br>' + badge(r.admission, r.admission_note) + '</td>'
          + '<td style="' + cell + ';background:' + heat(Math.min.apply(null, ps), Math.max.apply(null, ps), r.unit_price) + '">¥' + fmt1(r.unit_price) + ' × ' + fmt1(r.qty) + '<br><b>¥' + fmt1(r.total_price) + '</b></td>'
          + '<td style="' + cell + ';background:' + (r.lead_time_days == null ? 'transparent' : heat(Math.min.apply(null, ls), Math.max.apply(null, ls), r.lead_time_days)) + '">' + (r.lead_time_days == null ? '<i style="color:#999">交期 N/A</i>' : String(r.lead_time_days) + ' 天') + '</td>'
          + '<td style="' + cell + '">' + (r.hist_avg_price == null ? '—' : '¥' + fmt1(r.hist_avg_price)) + '</td>'
          + '<td style="' + cell + '">' + (r.pass_rate == null ? '—' : fmt1(r.pass_rate) + '%') + '</td>'
          + '<td style="' + cell + '"><b>' + (r.quality_score == null ? '—' : fmt1(r.quality_score)) + '</b>' + (r.rating ? ' <span style="border:1px solid #d9d9d9;border-radius:4px;padding:0 4px;font-size:11px">' + esc(r.rating) + '</span>' : '') + '</td>'
          + '<td style="' + cell + '">' + fmt1(r.price_score) + '</td>'
          + '<td style="' + cell + '">' + (r.lead_score == null ? '<i style="color:#999">N/A</i>' : fmt1(r.lead_score)) + '</td>'
          + '<td style="' + cell + '">' + bar + '</td>'
          + '<td style="' + cell + '"><details><summary style="cursor:pointer;color:#1677ff">算式</summary><div style="color:#555;max-width:330px">' + esc(r.formula) + '</div></details></td>'
          + '<td style="' + cell + '">' + choose + '</td></tr>';
      }).join('');
      return '<div style="border:1px solid #eee;border-radius:8px;margin-bottom:10px;overflow:hidden">'
        + '<div style="background:#fafafa;padding:6px 10px;font-weight:700">物料：' + esc(g.product_name) + ' <span style="color:#888;font-weight:400">（' + String(g.rows.length) + ' 家报价）</span></div>'
        + '<table style="border-collapse:collapse;width:100%"><thead><tr style="background:#fafafa;font-size:12px;color:#666">'
        + '<th style="padding:4px 8px;text-align:left">排名</th><th style="padding:4px 8px;text-align:left">供应商</th><th style="padding:4px 8px;text-align:left">报价</th><th style="padding:4px 8px;text-align:left">交期</th><th style="padding:4px 8px;text-align:left">历史成交</th><th style="padding:4px 8px;text-align:left">批次合格率</th><th style="padding:4px 8px;text-align:left">质量分</th><th style="padding:4px 8px;text-align:left">价格分</th><th style="padding:4px 8px;text-align:left">交期分</th><th style="padding:4px 8px;text-align:left">总分</th><th style="padding:4px 8px;text-align:left">计分明细</th><th style="padding:4px 8px;text-align:left">定标</th></tr></thead>'
        + '<tbody>' + rows + '</tbody></table></div>';
    }).join('');
  }
  if (m.ok === false) groupsHtml = '<div style="color:#cf1322;padding:8px 0">' + esc(m.error || '加载失败') + '</div>';
  const awardedBanner = m.awarded
    ? '<div style="background:#f9f0ff;border:1px solid #d3adf7;color:#722ed1;border-radius:8px;padding:8px 12px;margin-bottom:10px;font-weight:600">已定标 → ' + esc(m.awarded_po_code || 'PO') + '（中标：' + esc(m.awarded_supplier || '') + '）· 状态 ' + esc(m.rfq_status) + '</div>'
    : '';
  const modalRow = ((state.matrix && state.matrix.groups) || []).reduce((acc, g) => acc.concat(g.rows), []).find(r => r.quote_id === state.modal) || null;
  const modal = state.modal
    ? '<div style="position:fixed;inset:0;background:rgba(0,0,0,0.35);z-index:1000;display:flex;align-items:center;justify-content:center" data-act="modal-bg">'
      + '<div style="background:#fff;border-radius:10px;padding:18px;min-width:340px;box-shadow:0 8px 30px rgba(0,0,0,0.18)" data-act="modal-card">'
      + '<div style="font-weight:700;margin-bottom:8px">定标确认 — ' + esc(state.rfq) + '</div>'
      + '<div style="font-size:13px;color:#555;margin-bottom:10px"><b>' + esc(modalRow ? modalRow.supplier_name : ('报价行 #' + String(state.modal))) + '</b> 中标'
      + (modalRow ? ' · ¥' + fmt1(modalRow.unit_price) + '×' + fmt1(modalRow.qty) + '=¥' + fmt1(modalRow.total_price) + ' · ' + (modalRow.lead_time_days == null ? '交期 N/A' : '交期 ' + fmt1(modalRow.lead_time_days) + ' 天') + ' · 总分 ' + fmt1(modalRow.total_score) + ' · 排名#' + String(modalRow.rank) : '')
      + '，落选报价处置：</div>'
      + '<label style="display:block;font-size:13px;margin:4px 0"><input type="radio" name="w6b7-loser" value="cancel" checked /> 取消落选（status=lost）</label>'
      + '<label style="display:block;font-size:13px;margin:4px 0"><input type="radio" name="w6b7-loser" value="reserve" /> 保留后备（status=backup）</label>'
      + '<div style="margin-top:12px;text-align:right">'
      + '<button data-act="award" style="padding:4px 16px;border:1px solid #722ed1;color:#722ed1;background:#fff;border-radius:6px;margin-right:8px;cursor:pointer">确认定标</button>'
      + '<button data-act="modal-close" style="padding:4px 16px;border:1px solid #d9d9d9;color:#555;background:#fff;border-radius:6px;cursor:pointer">取消</button></div>'
      + '<div style="font-size:12px;color:#888;margin-top:8px">走引擎 POST /sourcing/award（会话身份推导，采购部/admin 围栏；CAS 幂等）</div></div></div>'
    : '';
  const ledger = state.awards.length === 0
    ? '<div style="color:#888;padding:6px 0">（暂无定标记录——PO 回链台账）</div>'
    : '<table style="border-collapse:collapse;width:100%;font-size:12px"><thead><tr style="background:#fafafa;color:#666">'
      + '<th style="padding:4px 8px;text-align:left">询价单</th><th style="padding:4px 8px;text-align:left">定标 PO</th><th style="padding:4px 8px;text-align:left">中标供应商</th><th style="padding:4px 8px;text-align:left">金额</th><th style="padding:4px 8px;text-align:left">PO 状态</th><th style="padding:4px 8px;text-align:left">需求日期</th></tr></thead><tbody>'
      + state.awards.map(a => '<tr>'
        + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + esc(a.rfq_code) + '</td>'
        + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0;color:#1677ff">' + esc(a.po_code) + '</td>'
        + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + esc(a.winner) + '</td>'
        + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">¥' + esc(a.amount) + '</td>'
        + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + esc(a.po_status) + '</td>'
        + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + esc(a.need_date || '') + '</td></tr>').join('')
      + '</tbody></table>';
  root.innerHTML = [
    '<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:8px">',
    '<b>询价单</b>',
    '<select data-w6b7-rfq style="padding:4px 8px;border:1px solid #d9d9d9;border-radius:6px;min-width:260px">' + rfqOptions + '</select>',
    m.rfq_status ? '<span style="color:' + statusColor(m.rfq_status) + ';font-weight:600">' + esc(m.rfq_status) + '</span>' : '',
    '<span style="flex:1"></span>',
    '<b>权重 价格</b><input data-w6b7-wp type="number" min="1" max="98" value="' + String(w.price) + '" style="width:56px;padding:2px 6px;border:1px solid #d9d9d9;border-radius:6px" />',
    '<b>交期</b><input data-w6b7-wl type="number" min="1" max="98" value="' + String(w.lead) + '" style="width:56px;padding:2px 6px;border:1px solid #d9d9d9;border-radius:6px" />',
    '<b>质量</b><input data-w6b7-wq type="number" min="1" max="98" value="' + String(w.quality) + '" style="width:56px;padding:2px 6px;border:1px solid #d9d9d9;border-radius:6px" />',
    '<button data-act="save-weights" style="padding:3px 12px;border:1px solid #1677ff;color:#1677ff;background:#fff;border-radius:6px;cursor:pointer">保存权重</button>',
    '<span style="font-size:12px;color:#888">（POST /sourcing/config → 排名即时重算）</span>',
    '</div>',
    awardedBanner,
    '<div data-w6b7-note style="font-size:12px;color:' + (String(state.note).indexOf('✗') === 0 ? '#cf1322' : '#389e0d') + ';margin-bottom:6px;min-height:16px">' + esc(state.note) + '</div>',
    groupsHtml,
    '<div style="border:1px solid #eee;border-radius:8px;padding:8px 10px;margin-top:12px"><div style="font-weight:700;margin-bottom:6px">定标台账（RFQ → PO 回链）</div>' + ledger + '</div>',
    modal,
  ].join('');
