const ROWS = ["pur_requests","pur_rfqs","pur_quotes","pur_orders","pur_invoices","pur_payments","wms_receipts","wms_shipments","wms_transfers","wms_counts","wms_stock","wms_movements","qm_inspections","qm_inspection_readings","qm_nc_dispositions","qm_aql_plans","mfg_orders","mfg_job_reports","mfg_material_issues","mfg_completions","so_orders","mps_plans","mrp_suggestions","srm_suppliers","srm_capas","kpi_snapshots","wfl_flow_configs","wfl_approval_todos","wfl_approval_records","departments","departmentsUsers","users"];
const ACTS = ["view","create","update","destroy","export"];
const esc = (s) => String(s == null ? "" : s).replace(/&/g,"&"+"amp;").replace(/</g,"&"+"lt;").replace(/>/g,"&"+"gt;").replace(/"/g,"&"+"quot;");
