// w6b8-aps-whatif: the upgrade marker (ensure + assert match this)
const ENGINE = String(window.__W6_ENGINE_BASE__ || 'http://127.0.0.1:13110');
const TOKEN = localStorage.getItem('NOCOBASE_TOKEN') || '';
const AMP = '\u0026';
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': AMP + 'amp;', '<': AMP + 'lt;', '>': AMP + 'gt;', '"': AMP + 'quot;', "'": AMP + '#39;' }[c]));
const state = { data: null, sim: null, note: '', busy: false };
const api = async (path, post) => {
  const resp = await fetch(ENGINE + path, post === undefined
    ? { headers: { authorization: 'Bearer ' + TOKEN } }
    : { method: 'POST', headers: { authorization: 'Bearer ' + TOKEN, 'content-type': 'application/json' }, body: JSON.stringify(post) });
  return { status: resp.status, ok: resp.ok, json: await resp.json().catch(() => ({})) };
};
const load = async () => {
  const out = await api('/aps/load?days=14');
  if (out.json && out.json.ok) state.data = out.json;
  paint();
};
const readKnobs = () => {
  const root = document.querySelector('[data-w6b8="aps-whatif"]');
  if (!root || !state.data) return { overtime: [], boost: [] };
  const overtime = [];
  for (const wc of state.data.workcenters || []) {
    const input = root.querySelector('[data-ot="' + String(wc.id) + '"]');
    if (!input) continue;
    const v = Math.round(Number(input.value || 0));
    if (v > 0) overtime.push({ wc_id: wc.id, extra_min: v });
  }
  const boost = [];
  for (const mo of state.data.open_mos || []) {
    const box = root.querySelector('[data-boost="' + String(mo.mo_id) + '"]');
    if (box && box.checked) boost.push(mo.mo_id);
  }
  return { overtime: overtime, boost: boost };
};
const runSim = async () => {
  if (state.busy) return;
  const knobs = readKnobs();
  state.busy = true; state.note = ''; paint();
  const out = await api('/aps/whatif', knobs);
  state.busy = false;
  if (out.json && out.json.ok) { state.sim = out.json; state.note = '✓ 模拟完成（只读计算——真实排产未变）'; }
  else state.note = '✗ ' + esc((out.json && (out.json.message || out.json.error)) || ('HTTP ' + String(out.status)));
  paint();
};
const promote = async () => {
  if (state.busy || !state.sim) return;
  if (!window.confirm('确认应用该场景到正式排产？将重写开放 planned 工序的计划日（planner/admin 围栏），并留存差异报告。')) return;
  const knobs = readKnobs();
  state.busy = true; paint();
  const out = await api('/aps/promote', Object.assign({}, knobs, { note: 'W6-B8 what-if 沙箱应用' }));
  state.busy = false;
  if (out.json && out.json.ok) { state.note = '✓ 已应用：重排 ' + String(out.json.applied) + ' 道工序，差异报告 run=#' + String(out.json.run_id) + ' 已留存'; state.sim = null; await load(); }
  else state.note = '✗ ' + esc((out.json && (out.json.message || out.json.error)) || ('HTTP ' + String(out.status)));
  paint();
};
function paint() {
  const root = document.querySelector('[data-w6b8="aps-whatif"]');
  if (!root) return;
  const d = state.data;
  if (!d) { root.innerHTML = '<div style="color:#888;padding:8px">加载中…</div>'; return; }
  const otRow = (d.workcenters || []).map(wc => '<label style="display:inline-flex;align-items:center;gap:4px;margin:2px 10px 2px 0;font-size:13px">' + esc(wc.code) + ' 加班 '
    + '<input data-ot="' + String(wc.id) + '" type="number" min="0" max="960" step="30" value="0" style="width:70px;padding:2px 6px;border:1px solid #d9d9d9;border-radius:6px" /> 分/日</label>').join('');
  const boostRow = (d.open_mos || []).map(mo => '<label style="display:inline-flex;align-items:center;gap:4px;margin:2px 10px 2px 0;font-size:13px"><input type="checkbox" data-boost="' + String(mo.mo_id) + '" /> ' + esc(mo.mo_code) + '（' + String(mo.open_ops) + ' 道开放工序' + (mo.need_date ? '·需 ' + esc(mo.need_date) : '') + '）</label>').join('') || '<span style="color:#888;font-size:13px">当前无可重排 MO</span>';
  const banner = '<div style="background:#f9f0ff;border:1px solid #d3adf7;color:#722ed1;border-radius:8px;padding:8px 12px;margin-bottom:10px;font-size:13px"><b>隔离规则</b>：模拟只读真实数据、零写入（mfg_order_operations 不因模拟变化）；只有点「应用（Promote）」才落库——限 计划部（PMC）/admin，留存差异报告（aps_whatif_runs）</div>';
  let simHtml = '<div style="color:#888;padding:6px 0">设置加班分钟或 MO 优先级后点「运行模拟」——展示前后对比（日期/超载标记/峰值负荷）</div>';
  const s = state.sim;
  if (s) {
    const deltas = s.deltas || [];
    const moved = deltas.filter(x => x.before_date !== x.after_date);
    const flipped = deltas.filter(x => x.overload_before !== x.overload_after);
    const deltaTable = moved.length === 0 && flipped.length === 0
      ? '<div style="color:#389e0d;padding:6px 0">本场景不改变任何工序日期与超载标记（与现行计划等价）</div>'
      : '<table style="border-collapse:collapse;width:100%;font-size:12px"><thead><tr style="background:#fafafa;color:#666">'
        + '<th style="padding:4px 8px;text-align:left">MO</th><th style="padding:4px 8px;text-align:left">工序</th><th style="padding:4px 8px;text-align:left">分钟</th><th style="padding:4px 8px;text-align:left">现计划日</th><th style="padding:4px 8px;text-align:left">模拟后</th><th style="padding:4px 8px;text-align:left">Δ</th><th style="padding:4px 8px;text-align:left">超载</th></tr></thead><tbody>'
        + deltas.filter(x => x.before_date !== x.after_date || x.overload_before !== x.overload_after).map(x => '<tr>'
          + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + esc(x.mo_code) + '</td>'
          + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + String(x.seq) + ' ' + esc(x.name) + '</td>'
          + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + String(x.minutes) + '</td>'
          + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + esc(x.before_date || '—') + (x.overload_before ? ' <span style="color:#cf1322">⚠超载</span>' : '') + '</td>'
          + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0"><b>' + esc(x.after_date) + '</b>' + (x.overload_after ? ' <span style="color:#cf1322">⚠超载</span>' : '') + '</td>'
          + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + (x.delta_days === 0 ? '同日' : (x.delta_days > 0 ? '+' : '') + String(x.delta_days) + ' 天') + '</td>'
          + '<td style="padding:4px 8px;border-bottom:1px solid #f0f0f0">' + (x.overload_before !== x.overload_after ? (x.overload_after ? '<span style="color:#cf1322">新增超载</span>' : '<span style="color:#389e0d">解除 ✓</span>') : '—') + '</td></tr>').join('')
        + '</tbody></table>';
    const peakRow = (s.peak || []).map(p => {
      const changed = p.before_peak !== p.after_peak;
      return '<span style="display:inline-block;margin:2px 10px 2px 0;font-size:12px;border:1px solid ' + (changed ? '#1677ff' : '#eee') + ';border-radius:6px;padding:2px 8px">' + esc(p.code) + ' 峰值负荷 ' + String(p.before_peak) + '% → <b>' + String(p.after_peak) + '%</b></span>';
    }).join('');
    const bucketRows = (s.bucket_delta || []).slice(0, 12).map(b => '<tr><td style="padding:3px 8px;border-bottom:1px solid #f0f0f0">#' + String(b.wc_id) + '</td><td style="padding:3px 8px;border-bottom:1px solid #f0f0f0">' + esc(b.date) + '</td><td style="padding:3px 8px;border-bottom:1px solid #f0f0f0">' + String(b.before) + '</td><td style="padding:3px 8px;border-bottom:1px solid #f0f0f0"><b>' + String(b.after) + '</b></td><td style="padding:3px 8px;border-bottom:1px solid #f0f0f0">' + String(b.capacity) + '</td></tr>').join('');
    simHtml = '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px">'
