// w6b8-calendar: the upgrade marker (ensure + assert match this)
const ENGINE = String(window.__W6_ENGINE_BASE__ || 'http://127.0.0.1:13110');
const TOKEN = localStorage.getItem('NOCOBASE_TOKEN') || '';
const AMP = '\u0026';
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': AMP + 'amp;', '<': AMP + 'lt;', '>': AMP + 'gt;', '"': AMP + 'quot;', "'": AMP + '#39;' }[c]));
const TODAY = new Date().toISOString().slice(0, 10);
const state = { month: TODAY.slice(0, 7), orders: [], sel: 0, note: '', busy: false };
const STATUS = { new: ['待受理', '#e6f4ff', '#1677ff'], accepted: ['维修中', '#fff7e6', '#d46b08'], done: ['待验收', '#fffbe6', '#d4b106'], closed: ['已验收', '#f6ffed', '#389e0d'] };
const SRC = { plan: '预防性计划', andon: '车间Andon', manual: '手动' };
const api = async (path, post) => {
  const resp = await fetch(ENGINE + path, post === undefined
    ? { headers: { authorization: 'Bearer ' + TOKEN } }
    : { method: 'POST', headers: { authorization: 'Bearer ' + TOKEN, 'content-type': 'application/json' }, body: JSON.stringify(post) });
  return { status: resp.status, ok: resp.ok, json: await resp.json().catch(() => ({})) };
};
const load = async () => {
  const out = await api('/eam/orders');
  state.orders = (out.json && out.json.orders) || [];
  paint();
};
const act = async (id, action, note, actualMin) => {
  if (state.busy) return;
  state.busy = true; paint();
  const out = await api('/eam/act', { order_id: id, action: action, note: note || '', actual_min: actualMin });
  state.busy = false;
  if (out.json && out.json.ok) { state.note = '✓ 工单 ' + esc(out.json.code) + ' 已' + (action === 'accept' ? '受理' : action === 'done' ? '完成维修（待验收）' : '验收关闭'); state.sel = 0; await load(); }
  else { state.note = '✗ ' + esc((out.json && (out.json.message || out.json.error)) || ('HTTP ' + String(out.status))); paint(); }
};
const monthOf = (offset) => {
  const y = Number(state.month.slice(0, 4)); const m = Number(state.month.slice(5, 7)) + offset;
  const d = new Date(Date.UTC(y, m - 1, 1));
  state.month = d.toISOString().slice(0, 7);
  paint();
};
const chip = (o) => {
  const meta = STATUS[o.status] || ['?', '#f5f5f5', '#8c8c8c'];
  const overdue = o.planned_date && o.planned_date < TODAY && (o.status === 'new' || o.status === 'accepted');
  return '<button data-act="sel" data-id="' + String(o.id) + '" style="display:block;width:100%;text-align:left;margin:2px 0;border:1px solid ' + (overdue ? '#ffa39e' : '#d9d9d9') + ';border-left:4px solid ' + (overdue ? '#cf1322' : meta[2]) + ';border-radius:6px;background:' + meta[1] + ';padding:2px 6px;font-size:12px;cursor:pointer">'
    + esc(o.code) + ' · ' + esc(o.asset_code || o.workcenter_name || '?') + (overdue ? ' <b style="color:#cf1322">逾期</b>' : '') + '</button>';
};
function paint() {
  const root = document.querySelector('[data-w6b8="calendar"]');
  if (!root) return;
  const y = Number(state.month.slice(0, 4)); const m = Number(state.month.slice(5, 7));
  const firstDay = new Date(Date.UTC(y, m - 1, 1));
  const daysInMonth = new Date(Date.UTC(y, m, 0)).getUTCDate();
  const lead = (firstDay.getUTCDay() + 6) % 7;
  const cells = [];
  for (let i = 0; i < lead; i += 1) cells.push('<td style="border:1px solid #f0f0f0;min-height:64px"></td>');
  for (let d = 1; d <= daysInMonth; d += 1) {
    const iso = state.month + '-' + (d < 10 ? '0' : '') + String(d);
    const dayOrders = state.orders.filter(o => o.planned_date === iso);
    const isToday = iso === TODAY;
    cells.push('<td style="border:1px solid ' + (isToday ? '#1677ff' : '#f0f0f0') + ';vertical-align:top;padding:3px;width:14.2%;min-height:64px">'
      + '<div style="font-size:12px;color:' + (isToday ? '#1677ff' : '#888') + ';font-weight:' + (isToday ? '700' : '400') + '">' + String(d) + '</div>'
      + dayOrders.map(chip).join('') + '</td>');
  }
  while (cells.length % 7 !== 0) cells.push('<td style="border:1px solid #f0f0f0"></td>');
  const rows = [];
  for (let i = 0; i < cells.length; i += 7) rows.push('<tr>' + cells.slice(i, i + 7).join('') + '</tr>');
  const sel = state.orders.find(o => o.id === state.sel) || null;
  const detail = sel
    ? '<div style="border:1px solid #d9d9d9;border-radius:8px;padding:10px 12px;margin-top:10px">'
      + '<div style="font-weight:700;margin-bottom:4px">' + esc(sel.code) + ' · ' + esc(sel.asset_name || sel.asset_code || '?') + (sel.asset_code ? '（' + esc(sel.asset_code) + '）' : '') + '</div>'
      + '<div style="font-size:13px;color:#555;margin-bottom:4px">来源 ' + esc(SRC[sel.source] || sel.source) + ' · 优先级 ' + esc(sel.priority) + ' · 计划日 ' + esc(sel.planned_date || '—') + ' · 发起 ' + esc(sel.requested_by) + (sel.accepted_by ? ' · 受理 ' + esc(sel.accepted_by) : '') + (sel.mo_code ? ' · 关联 ' + esc(sel.mo_code) : '') + '</div>'
      + '<div style="font-size:13px;color:#333;margin-bottom:8px">' + esc(sel.problem) + '</div>'
      + (sel.status === 'new' ? '<button data-act="accept" style="padding:4px 16px;border:1px solid #1677ff;color:#1677ff;background:#fff;border-radius:6px;cursor:pointer">受理开工</button>' : '')
      + (sel.status === 'accepted' ? '<div style="margin-bottom:6px"><input data-in="note" placeholder="维修说明（必填）" style="width:60%;padding:4px 8px;border:1px solid #d9d9d9;border-radius:6px" /> <input data-in="min" type="number" placeholder="工时分" style="width:90px;padding:4px 8px;border:1px solid #d9d9d9;border-radius:6px" /></div>'
        + '<button data-act="done" style="padding:4px 16px;border:1px solid #d46b08;color:#d46b08;background:#fff;border-radius:6px;cursor:pointer">完成维修（转待验收）</button>' : '')
      + (sel.status === 'done' ? '<button data-act="close" style="padding:4px 16px;border:1px solid #389e0d;color:#389e0d;background:#fff;border-radius:6px;cursor:pointer">验收关闭（限发起人/admin）</button>' : '')
      + (sel.status === 'closed' ? '<span style="color:#389e0d">已验收关闭</span>' : '')
      + '</div>'
    : '<div style="color:#888;padding:8px 0">点击日历中的工单条查看详情并处理（受理/完成/验收走引擎状态机）</div>';
  const legend = Object.keys(STATUS).map(k => '<span style="display:inline-block;margin-right:10px;font-size:12px"><span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:' + STATUS[k][1] + ';border:1px solid ' + STATUS[k][2] + ';margin-right:4px;vertical-align:-1px"></span>' + STATUS[k][0] + '</span>').join('')
    + '<span style="font-size:12px;margin-left:6px"><span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:#fff1f0;border:1px solid #cf1322;margin-right:4px;vertical-align:-1px"></span>逾期（计划日已过未完成）</span>';
  root.innerHTML = [
    '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">',
    '<button data-act="prev" style="padding:2px 12px;border:1px solid #d9d9d9;border-radius:6px;cursor:pointer">‹</button>',
    '<b style="font-size:16px">' + String(y) + ' 年 ' + String(m) + ' 月 · 维保日历</b>',
    '<button data-act="next" style="padding:2px 12px;border:1px solid #d9d9d9;border-radius:6px;cursor:pointer">›</button>',
    '<span style="flex:1"></span><button data-act="reload" style="padding:2px 12px;border:1px solid #d9d9d9;border-radius:6px;cursor:pointer">刷新</button></div>',
    '<div style="margin-bottom:6px">' + legend + '</div>',
    '<table style="border-collapse:collapse;width:100%;table-layout:fixed"><thead><tr style="background:#fafafa;font-size:12px;color:#666">'
    + ['一', '二', '三', '四', '五', '六', '日'].map(d => '<th style="padding:4px;border:1px solid #f0f0f0">周' + d + '</th>').join('') + '</tr></thead>'
    + '<tbody>' + rows.join('') + '</tbody></table>',
    detail,
    '<div data-w6b8-note style="font-size:12px;color:' + (String(state.note).indexOf('✗') === 0 ? '#cf1322' : '#389e0d') + ';margin-top:6px;min-height:16px">' + esc(state.note) + '</div>',
  ].join('');
};
ctx.render('<div data-w6b8="calendar" style="padding:8px;font-family:system-ui"></div>');
const root = () => document.querySelector('[data-w6b8="calendar"]');
document.addEventListener('click', (ev) => {
  const t = ev.target && ev.target.closest ? ev.target.closest('[data-act]') : null;
  if (!t || !root() || !root().contains(t)) return;
  const kind = t.getAttribute('data-act');
  if (kind === 'prev') return monthOf(-1);
  if (kind === 'next') return monthOf(1);
  if (kind === 'reload') { state.note = ''; return void load(); }
  if (kind === 'sel') { state.sel = Number(t.getAttribute('data-id')); state.note = ''; return paint(); }
  if (kind === 'accept') return void act(state.sel, 'accept');
  if (kind === 'done') {
    const panel = root().querySelector('[data-in="note"]');
    const mins = root().querySelector('[data-in="min"]');
    return void act(state.sel, 'done', panel ? panel.value : '', mins ? Number(mins.value) : NaN);
  }
  if (kind === 'close') return void act(state.sel, 'close');
});
void load();

