  const timeline = vbs.map(b => {
    const st = STATUS[b.bom_status] || ['#8c8c8c', b.bom_status];
    const eco = ecoByTo[b.id];
    return `<div style="border:2px solid ${st[0]};border-radius:10px;padding:8px 12px;min-width:150px">
      <div style="font-weight:700">v${esc(b.version)} ${b.is_default ? '<span style="color:#389e0d">★默认</span>' : ''}</div>
      <div style="font-size:12px;color:#555">${esc(b.code)} · <span style="color:${st[0]};font-weight:600">${st[1]}</span></div>
      ${eco ? `<div style="font-size:12px;margin-top:2px">ECO ${esc(eco.code)}（${esc(eco.doc_status)}）</div>` : ''}
    </div>`;
  }).join('<div style="align-self:center;color:#999">→</div>');
  const diffSelA = document.querySelector('[data-w6b4-diff-a]');
  const diffSelB = document.querySelector('[data-w6b4-diff-b]');
  let diffHtml = '<div style="color:#888;padding:6px 0">选择两个版本对比行差异</div>';
  if (diffSelA && diffSelB && diffSelA.value && diffSelB.value) {
    const la = lines.filter(l => Number(l.bom_id) === Number(diffSelA.value));
    const lb = lines.filter(l => Number(l.bom_id) === Number(diffSelB.value));
    const key = (l) => Number(l.product_id);
    const rowHtml = (name, text, color, extra) => `<div style="display:flex;gap:8px;padding:3px 8px;border-left:4px solid ${color}"><span style="flex:1">${esc(name)}</span><span style="color:${color};font-weight:600">${esc(text)}</span><span style="color:#888">${esc(extra || '')}</span></div>`;
    const parts = [];
    for (const l of lb) {
      const old = la.find(x => key(x) === key(l));
      if (!old) parts.push(rowHtml(prodName[l.product_id] || ('#' + l.product_id), '新增 ' + l.qty_per_unit + l.uom + '/单位', '#1677ff'));
      else if (Number(old.qty_per_unit) !== Number(l.qty_per_unit)) parts.push(rowHtml(prodName[l.product_id] || ('#' + l.product_id), l.qty_per_unit + '（原 ' + old.qty_per_unit + '）' + l.uom + '/单位', '#1677ff', '用量变更'));
      else parts.push(rowHtml(prodName[l.product_id] || ('#' + l.product_id), l.qty_per_unit + ' ' + (l.uom || '') + '/单位 损耗' + (l.scrap_pct || 0) + '%', '#333'));
    }
    for (const l of la) if (!lb.some(x => key(x) === key(l))) parts.push(rowHtml(prodName[l.product_id] || ('#' + l.product_id), '移除 ' + l.qty_per_unit + ' ' + (l.uom || '') + '/单位', '#cf1322'));
    diffHtml = parts.join('') || '<div style="color:#888">两版本行完全一致</div>';
  }
  const ecoSel = document.querySelector('[data-w6b4-eco]');
  let impactHtml = '<div style="color:#888;padding:6px 0">选择 ECO 查看影响分析</div>';
  if (ecoSel && ecoSel.value) {
    const eco = ecos.find(e => String(e.id) === String(ecoSel.value));
    if (eco) {
      const imp = typeof eco.impact === 'string' ? JSON.parse(eco.impact) : (eco.impact || {});
      const listRows = (rows, fmt) => (rows || []).map(fmt).join('') || '<div style="color:#999;padding:2px 8px">（无）</div>';
      impactHtml = `<div style="font-weight:700;margin:6px 0 2px">受影响在产 MO</div>` +
        listRows(imp.in_progress_mos, (m) => `<div style="padding:2px 8px">${esc(m.code)} · ${esc(m.doc_status)} · 计划 ${m.qty}（仍按原版本执行）</div>`)
        + `<div style="font-weight:700;margin:6px 0 2px">受影响库存批次（成品）</div>`
        + listRows(imp.fg_lots, (l) => `<div style="padding:2px 8px">${esc(l.lot_no)} · ${esc(l.production_date || '')} · ${esc(l.status || '')}</div>`)
        + `<div style="font-weight:700;margin:6px 0 2px">受影响未交付 SO</div>`
        + listRows(imp.undelivered_sos, (s) => `<div style="padding:2px 8px">${esc(s.code)} · ${esc(s.doc_status)} · ${esc(s.shipping_status || '')}</div>`);
    }
  }
  root.innerHTML = `
  <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:8px">
    <b>产品</b><select data-w6b4-prod style="padding:4px 8px;border:1px solid #d9d9d9;border-radius:6px">
      ${[...new Set(boms.map(b => Number(b.product_id)))].map(id => `<option value="${id}" ${id === pid ? 'selected' : ''}>${esc(prodName[id] || ('#' + id))}</option>`).join('')}
    </select>
    <b style="margin-left:12px">版本对比</b>
    <select data-w6b4-diff-a style="padding:4px 8px;border:1px solid #d9d9d9;border-radius:6px">
      <option value="">基准版本</option>${vbs.map(b => `<option value="${b.id}" ${String(b.id) === String(diffSelA ? diffSelA.value : '') ? 'selected' : ''}>v${esc(b.version)} ${esc(b.code)}</option>`).join('')}</select>
    <span>→</span>
    <select data-w6b4-diff-b style="padding:4px 8px;border:1px solid #d9d9d9;border-radius:6px">
      <option value="">对比版本</option>${vbs.map(b => `<option value="${b.id}" ${String(b.id) === String(diffSelB ? diffSelB.value : '') ? 'selected' : ''}>v${esc(b.version)} ${esc(b.code)}</option>`).join('')}</select>
    <span style="color:#1677ff">■ 新增/变更</span><span style="color:#333">■ 不变</span><span style="color:#cf1322">■ 移除</span>
  </div>
  <div data-w6b4-timeline style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">${timeline || '<span style="color:#888">该产品暂无 BOM 版本</span>'}</div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
    <div style="border:1px solid #eee;border-radius:8px;padding:8px"><div style="font-weight:700;margin-bottom:4px">行差异（蓝=新增/变更 黑=不变 红=移除）</div><div style="max-height:280px;overflow:auto">${diffHtml}</div></div>
    <div style="border:1px solid #eee;border-radius:8px;padding:8px">
      <div style="display:flex;gap:8px;align-items:center;margin-bottom:4px"><b style="white-space:nowrap">影响分析</b>
        <select data-w6b4-eco style="padding:4px 8px;border:1px solid #d9d9d9;border-radius:6px;flex:1">
          <option value="">选择 ECO</option>${ecos.slice().sort((a, b) => b.id - a.id).map(e => `<option value="${e.id}" ${ecoSel && String(e.id) === String(ecoSel.value) ? 'selected' : ''}>${esc(e.code)} ${esc(e.title)}（${esc(e.doc_status)}）</option>`).join('')}</select>
        <button data-w6b4-submit style="padding:4px 12px;border:1px solid #1677ff;color:#1677ff;background:#fff;border-radius:6px;cursor:pointer">送审所选 ECO</button>
      </div>
      <div style="max-height:280px;overflow:auto">${impactHtml}</div>
      <div data-w6b4-note style="font-size:12px;color:#888;margin-top:4px">送审走引擎 POST /eco/submit（会话身份推导，planner/质检/admin 围栏）；审批通过后引擎自动切版本：新版生效★、旧版停用，在产 MO 不受影响</div>
    </div>
  </div>`;
};
window.__w6b4PlmRender = render;
setTimeout(() => { render();
  for (const s of document.querySelectorAll('[data-w6b4-prod],[data-w6b4-diff-a],[data-w6b4-diff-b],[data-w6b4-eco]')) {
    s.addEventListener('change', render);
  }
  const btn = document.querySelector('[data-w6b4-submit]');
  if (btn) btn.addEventListener('click', async () => {
    const root = document.querySelector('[data-w6b4="plm-console"]');
    const ecoSel2 = root.querySelector('[data-w6b4-eco]');
    const note = root.querySelector('[data-w6b4-note]');
    if (!ecoSel2.value) { note.textContent = '先选择一张 ECO'; return; }
    const eco = ecos.find(e => String(e.id) === String(ecoSel2.value));
    btn.disabled = true; btn.textContent = '送审中…';
    const out = await callEngine('/eco/submit', { eco_code: eco.code });
    note.textContent = out.ok ? `已送审 ${eco.code}（引擎受理，刷新后状态见列表）` : `送审被拒：${(out.json && out.json.error) || out.status}`;
    btn.disabled = false; btn.textContent = '送审所选 ECO';
  });
}, 0);

